import React from 'react';
import type { PropsWithChildren, ReactNode } from 'react';
import { isElement } from 'react-is';

import { SelectTriggerWidthOptionsType } from './types.js';
import { DataTestId } from '../../core/types/data-props.js';
import { StylingProps } from '../../core/types/styling-props.js';

export type SelectV2TriggerProps = PropsWithChildren &
  StylingProps &
  DataTestId & {
    /**
     * The placeholder text displayed in the SelectV2.Trigger.
     */
    placeholder?: ReactNode;
    /**
     * The width of the SelectV2.Trigger.
     * @defaultValue 'content'
     */
    width?: SelectTriggerWidthOptionsType;
  };

/**
 * Typeguard function that will check if a React.Node is a SelectV2.Trigger
 * @internal
 */
export function _isSelectV2TriggerElement(
  child: React.ReactNode,
): child is React.ReactElement<SelectV2TriggerProps> {
  if (isElement(child) && child.type === SelectV2Trigger) {
    return true;
  }
  return false;
}

export function SelectV2Trigger(props: SelectV2TriggerProps) {
  return null;
}
SelectV2Trigger.displayName = 'SelectV2.Trigger';
